// Fused softmax kernel — one block per row.
__global__ void softmax_row(const float* __restrict__ x, float* __restrict__ y, int B, int N) {
    int row = blockIdx.x;
    if (row >= B) return;
    const float* xr = x + row * N;
    float* yr = y + row * N;
    extern __shared__ float sdata[];
    // Pass 1: max
    float local_max = -INFINITY;
    for (int j = threadIdx.x; j < N; j += blockDim.x) local_max = fmaxf(local_max, xr[j]);
    sdata[threadIdx.x] = local_max;
    __syncthreads();
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) sdata[threadIdx.x] = fmaxf(sdata[threadIdx.x], sdata[threadIdx.x + offset]);
        __syncthreads();
    }
    float m = sdata[0];
    // Pass 2: exp + partial sum
    float local_sum = 0.f;
    for (int j = threadIdx.x; j < N; j += blockDim.x) {
        float v = expf(xr[j] - m); yr[j] = v; local_sum += v;
    }
    sdata[threadIdx.x] = local_sum;
    __syncthreads();
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) sdata[threadIdx.x] += sdata[threadIdx.x + offset];
        __syncthreads();
    }
    float s = sdata[0];
    // Pass 3: normalize
    float inv = 1.0f / s;
    for (int j = threadIdx.x; j < N; j += blockDim.x) yr[j] *= inv;
}

__global__ void rmsnorm(const float* x, const float* gamma, float* y, int B, int N, float eps) {
    int row = blockIdx.x; if (row >= B) return;
    const float* xr = x + row*N; float* yr = y + row*N;
    extern __shared__ float sdata[];
    float local = 0.f;
    for (int j = threadIdx.x; j < N; j += blockDim.x) { float v = xr[j]; local += v*v; }
    sdata[threadIdx.x] = local; __syncthreads();
    for (int o = blockDim.x/2; o > 0; o >>= 1) { if (threadIdx.x < o) sdata[threadIdx.x] += sdata[threadIdx.x + o]; __syncthreads(); }
    float r = rsqrtf(sdata[0]/N + eps);
    for (int j = threadIdx.x; j < N; j += blockDim.x) yr[j] = xr[j] * r * gamma[j];
}

__global__ void layernorm(const float* x, const float* gamma, const float* beta, float* y, int B, int N, float eps) {
    int row = blockIdx.x; if (row >= B) return;
    const float* xr = x + row*N; float* yr = y + row*N;
    extern __shared__ float sdata[];
    float local_sum = 0.f; for (int j = threadIdx.x; j < N; j += blockDim.x) local_sum += xr[j];
    sdata[threadIdx.x] = local_sum; __syncthreads();
    for (int o = blockDim.x/2; o > 0; o >>= 1) { if (threadIdx.x < o) sdata[threadIdx.x] += sdata[threadIdx.x+o]; __syncthreads(); }
    float mu = sdata[0] / N;
    float local_var = 0.f; for (int j = threadIdx.x; j < N; j += blockDim.x) { float d = xr[j]-mu; local_var += d*d; }
    sdata[threadIdx.x] = local_var; __syncthreads();
    for (int o = blockDim.x/2; o > 0; o >>= 1) { if (threadIdx.x < o) sdata[threadIdx.x] += sdata[threadIdx.x+o]; __syncthreads(); }
    float inv = rsqrtf(sdata[0]/N + eps);
    for (int j = threadIdx.x; j < N; j += blockDim.x) yr[j] = (xr[j]-mu)*inv*gamma[j] + beta[j];
}

// Simplified Flash-attention forward (single block per row tile).
__global__ void flash_attn_fwd(const float* Q, const float* K, const float* V, float* O,
                                int T, int d, float scale) {
    int row = blockIdx.x; // one block per query row
    extern __shared__ float smem[];
    float* q_s = smem;
    float* o_s = q_s + d;
    for (int i = threadIdx.x; i < d; i += blockDim.x) { q_s[i] = Q[row*d+i]; o_s[i] = 0.f; }
    __syncthreads();
    float m_i = -INFINITY; float l_i = 0.f;
    for (int j = 0; j < T; ++j) {
        // s_j = dot(Q_row, K[j])
        float s = 0.f;
        for (int t = threadIdx.x; t < d; t += blockDim.x) s += q_s[t] * K[j*d + t];
        // block reduce s (omitted detail)
        s = s * scale;
        float m_new = fmaxf(m_i, s);
        float p = expf(s - m_new);
        float alpha = expf(m_i - m_new);
        for (int t = threadIdx.x; t < d; t += blockDim.x) o_s[t] = o_s[t]*alpha + p*V[j*d+t];
        l_i = l_i*alpha + p;
        m_i = m_new;
    }
    for (int t = threadIdx.x; t < d; t += blockDim.x) O[row*d+t] = o_s[t] / l_i;
}

__global__ void spmm_csr(const int* rowptr, const int* colidx, const float* vals,
                          const float* B, float* Y, int M, int K, int N) {
    int row = blockIdx.x; if (row >= M) return;
    int j_start = rowptr[row], j_end = rowptr[row+1];
    for (int n = threadIdx.x; n < N; n += blockDim.x) {
        float acc = 0.f;
        for (int j = j_start; j < j_end; ++j) acc += vals[j] * B[colidx[j]*N + n];
        Y[row*N + n] = acc;
    }
}

// Trivial segmented reduce: one block per segment (assumes segments are short).
__global__ void seg_reduce(const float* values, const int* seg_starts, float* out, int G) {
    int g = blockIdx.x; if (g >= G) return;
    int s = seg_starts[g], e = seg_starts[g+1];
    float acc = 0.f;
    for (int i = s + threadIdx.x; i < e; i += blockDim.x) acc += values[i];
    // block reduce omitted; assume blockDim.x == 1 for clarity.
    out[g] = acc;
}

__global__ void batched_gemv(const float* A, const float* x, float* y, int B, int M, int N) {
    int b = blockIdx.y; int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (b >= B || i >= M) return;
    const float* Ab = A + b*M*N; const float* xb = x + b*N; float* yb = y + b*M;
    float acc = 0.f; for (int j = 0; j < N; ++j) acc += Ab[i*N + j] * xb[j];
    yb[i] = acc;
}

// Single-block Blelloch scan sketch (input size <= 2*blockDim.x).
__global__ void scan_block(float* x, int N) {
    extern __shared__ float s[];
    int tid = threadIdx.x;
    s[2*tid] = (2*tid < N) ? x[2*tid] : 0.f;
    s[2*tid+1] = (2*tid+1 < N) ? x[2*tid+1] : 0.f;
    int offset = 1;
    for (int d = N>>1; d > 0; d >>= 1) {
        __syncthreads();
        if (tid < d) { int ai = offset*(2*tid+1)-1, bi = offset*(2*tid+2)-1; s[bi] += s[ai]; }
        offset *= 2;
    }
    if (tid == 0) s[N-1] = 0.f;
    for (int d = 1; d < N; d *= 2) {
        offset >>= 1; __syncthreads();
        if (tid < d) { int ai = offset*(2*tid+1)-1, bi = offset*(2*tid+2)-1; float t = s[ai]; s[ai] = s[bi]; s[bi] += t; }
    }
    __syncthreads();
    if (2*tid < N)   x[2*tid]   = s[2*tid];
    if (2*tid+1 < N) x[2*tid+1] = s[2*tid+1];
}

__global__ void conv1d(const float* x, const float* w, float* y, int N, int K) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= N) return;
    int half = K / 2; float acc = 0.f;
    for (int k = 0; k < K; ++k) { int xi = i + k - half; if (xi >= 0 && xi < N) acc += w[k] * x[xi]; }
    y[i] = acc;
}

__global__ void top_k_repeated_max(const float* x, float* out, int N, int K) {
    extern __shared__ float buf[];
    if (threadIdx.x == 0) for (int i = 0; i < N; ++i) buf[i] = x[i];
    __syncthreads();
    if (threadIdx.x == 0) {
        for (int k = 0; k < K; ++k) {
            int best = 0; float bv = -INFINITY;
            for (int i = 0; i < N; ++i) if (buf[i] > bv) { bv = buf[i]; best = i; }
            out[k] = bv; buf[best] = -INFINITY;
        }
    }
}

__global__ void adam_step(float* p, float* g, float* m, float* v,
                          float lr, float b1, float b2, float eps, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= N) return;
    float mi = b1*m[i] + (1.f - b1)*g[i];
    float vi = b2*v[i] + (1.f - b2)*g[i]*g[i];
    p[i] -= lr * mi / (sqrtf(vi) + eps);
    m[i] = mi; v[i] = vi;
}

// Plain GEMM; the QKV split is a reshape on the host after.
__global__ void gemm(const float* A, const float* B, float* C, int M, int K, int N) {
    int r = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (r >= M || c >= N) return;
    float acc = 0.f; for (int k = 0; k < K; ++k) acc += A[r*K+k]*B[k*N+c];
    C[r*N+c] = acc;
}
